-- GENERATED BY QueryOne AT 2021-03-04 14:17:59
-- USING SYSTEM@172.31.120.104:1531(OSGGDB2)

CREATE OR REPLACE FUNCTION ECAMS.SRSTEPINFO
(ISRID IN VARCHAR2)
RETURN VARCHAR2
IS
   VCNT  INT := 0;
   RETSTEP VARCHAR2(100);

BEGIN
    RETSTEP := '41';

    --개발계획작성여부
    SELECT COUNT(*)
      INTO VCNT
      FROM CMC0110
     WHERE CC_SRID=ISRID
       AND CC_STATUS<>'3'
       AND CC_DEVTIME IS NOT NULL;
    IF VCNT > 0 THEN
       RETSTEP := RETSTEP || ',42';
--    ELSE
--       RETURN RETSTEP;
    END IF;

    --프로그램유무
    SELECT COUNT(*)
      INTO VCNT
      FROM CMR1000 A
     WHERE A.CR_ITSMID=ISRID
       AND A.CR_STATUS<>'3';
    IF VCNT > 0 THEN
       RETSTEP := RETSTEP || ',92,93';
    END IF;

    --단위테스트작성여부
    SELECT COUNT(*)
      INTO VCNT
      FROM CMC0200
     WHERE CC_SRID=ISRID
       AND CC_STATUS<>'3';
    IF VCNT > 0 THEN
       RETSTEP := RETSTEP || ',43';
    END IF;

    --통합테스트작성여부
    SELECT COUNT(*)
      INTO VCNT
      FROM CMC0210
     WHERE CC_SRID=ISRID
       AND CC_STATUS<>'3';
    IF VCNT > 0 THEN
       RETSTEP := RETSTEP || ',44';
    END IF;

    --적용확인
    /*
    SELECT COUNT(*)
      INTO VCNT
      FROM CMC0290
     WHERE CC_SRID=ISRID
       AND CC_GBNCD<>'E';
    IF VCNT > 0 THEN
       RETSTEP := RETSTEP || ',61,62';
    END IF;
    */

    --모니터링
    SELECT COUNT(*)
      INTO VCNT
      FROM CMC0202
     WHERE CC_SRID=ISRID;
    IF VCNT > 0 THEN
       RETSTEP := RETSTEP || ',63';
    END IF;

    --SR종료
    SELECT COUNT(*)
      INTO VCNT
      FROM CMC0290
     WHERE CC_SRID=ISRID
       AND CC_GBNCD='E';
    IF VCNT > 0 THEN
       RETSTEP := RETSTEP || ',69';
    END IF;


    RETURN RETSTEP;
end;